\begin{eqnarray}
\label{eq:CSopt}
\textbf{x}^* = \underset{\textbf{x} \in \{0,1,2\}^N}{argmin} \|\textbf{x}\|_{1} \quad {\mbox s.t.} \: \:
||\frac{1}{2} \hat{M}\textbf{x}-\frac{1}{r}\textbf{z}||_2 < \epsilon
\end{eqnarray}

